/**
 * `virtual:pwa-register` is generated by vite-plugin-pwa, which only runs in
 * vite.config.ts — so under vitest the specifier doesn't resolve at all, and
 * Vite fails the whole module at import-analysis time rather than at the
 * dynamic import. That kills any test that renders the root layout, even
 * though the layout guards the import with `import.meta.env.PROD` and never
 * reaches it. Hence a stub, not a `vi.mock`: the mock runs too late.
 *
 * Registering nothing is the honest stand-in — a test that wants the SW
 * lifecycle wants a real browser, not this.
 */
export function registerSW(): (reloadPage?: boolean) => Promise<void> {
	return async () => {};
}
